import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.StatusCode;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class OrderProcessingService {

    private final Tracer tracer;
    private final RestTemplate restTemplate;

    public OrderProcessingService(Tracer tracer, RestTemplate restTemplate) {
        this.tracer = tracer;
        this.restTemplate = restTemplate;
    }

    public void processOrder(String orderId) {
        Span span = tracer.spanBuilder("OrderProcessingService.processOrder")
                .setAttribute("order.id", orderId)
                .startSpan();

        try (io.opentelemetry.context.Scope scope = span.makeCurrent()) {
            // The W3C TraceContext headers are automatically injected into RestTemplate requests
            String inventoryUrl = "http://inventory-service/check?orderId=" + orderId;
            restTemplate.getForObject(inventoryUrl, String.class);

            span.setStatus(StatusCode.OK);
        } catch (Exception e) {
            span.recordException(e);
            span.setStatus(StatusCode.ERROR, "Failed to process order: " + e.getMessage());
            throw e;
        } finally {
            span.end();
        }
    }
}
